function getProperty<T, K extends keyof T>(obj: T, key: K): T[K] {
  return obj[key];
}

const user = { id: 42, name: "Alex", admin: false };

const id = getProperty(user, "id");      // тип: number
const name = getProperty(user, "name");  // тип: string
getProperty(user, "email");
// error TS2345: Argument of type '"email"' is not assignable
//   to parameter of type '"id" | "name" | "admin"'.

type UserValues = (typeof user)[keyof typeof user];  // string | number | boolean

function byId<T extends { id: string }>(items: T[], id: string): T | undefined {
  return items.find((i) => i.id === id);
}

const found = byId([{ id: "u1", name: "Alex", admin: true }], "u1");
// тип: { id: string; name: string; admin: boolean } | undefined
byId([{ id: 1 }], "1");
// error: Type 'number' is not assignable to type 'string'.

